function Stopwatch() {
  const [elapsed, setElapsed] = useState(0);
  const intervalRef = useRef(null); // survives re-renders, never triggers one

  const start = () => {
    intervalRef.current = setInterval(
      () => setElapsed(e => e + 1),
      1000
    );
  };

  const stop = () => clearInterval(intervalRef.current);

  return <button onClick={elapsed === 0 ? start : stop}>{elapsed}s</button>;
}

