from functools import lru_cache, cached_property

class Bad:
    @lru_cache(maxsize=256)   # holds a ref to every `self` forever
    def expensive(self, year: int) -> list:
        return self._compute(year)

class Good:
    @cached_property           # stored on instance, GC'd with it
    def summary(self) -> dict:
        return self._build()

    def expensive(self, year: int) -> list:
        cache = self.__dict__.setdefault('_exp_cache', {})
        if year not in cache:
            cache[year] = self._compute(year)
        return cache[year]

