func run(ctx context.Context) (string, error) {
    ch := make(chan string, 1) // buffered: send won't block if caller left
    go func() {
        result := slowWork()
        select {
        case ch <- result:
        case <-ctx.Done(): // exit cleanly if caller already returned
        }
    }()
    select {
    case r := <-ch:
        return r, nil
    case <-ctx.Done():
        return "", ctx.Err()
    }
}

import hashlib, bisect

class Ring:
    def __init__(self, nodes, replicas=100):
        self.ring, self.keys = {}, []
        for node in nodes:
            for i in range(replicas):
                h = int(hashlib.md5(f"{node}:{i}".encode()).hexdigest(), 16)
                self.ring[h] = node
                bisect.insort(self.keys, h)

    def get(self, key: str) -> str:
        h = int(hashlib.md5(key.encode()).hexdigest(), 16)
        i = bisect.bisect(self.keys, h) % len(self.keys)
        return self.ring[self.keys[i]]

