// Leaked goroutine — caller exits on timeout, send blocks forever
func doWork(ctx context.Context) {
    ch := make(chan int) // unbuffered
    go func() {
        result := compute()
        ch <- result // parks here if caller already returned
    }()
    select {
    case v := <-ch:
        use(v)
    case <-ctx.Done():
        return // goroutine is now permanently blocked
    }
}

