func readConfig(path string) (err error) {
	f, err := os.Open(path)
	if err != nil {
		return
	}
	defer func() {
		f.Close()
		if err != nil {
			// replaces whatever err was set to before return
			err = fmt.Errorf("readConfig %s: %w", path, err)
		}
	}()
	return decode(f) // if decode fails, defer wraps the error
}

