    @functools.lru_cache(maxsize=128)
    def load(self, key: str) -> bytes: ...

class BetterLoader:
    # GOOD: result lives in instance.__dict__; GC'd with the instance
    @functools.cached_property
    def config(self) -> dict:
        return _fetch_config()

